window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5855db575eab3985"]={"versions": [{"id": "FIG-5855db575eab3985", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).</li>\n<li><strong>Architektur-Kontext:</strong> Bestandteil des <em>AUTOSAR Generic Structure Template</em> (TPS_GenericStructureTemplate, Kapitel <em>Documentation Support / Formula Overview</em>).</li>\n<li><strong>Funktionaler Zweck:</strong> Definiert die formale Datenstruktur zur sprachunabhängigen und mehrsprachigen Repräsentation mathematischer Formeln (<code>MlFormula</code>) und technischer Gleichungen innerhalb von AUTOSAR-ARXML-Dateien (z. B. in Spezifikationsblöcken, Requirements-Traces und Software-Komponenten-Beschreibungen).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>MlFormula</code></strong> (realisiert <code>Paginateable</code>):</li>\n<li>Zentraler Container für mathematische Ausdrücke.</li>\n<li><strong><code>Caption</code></strong> (realisiert <code>MultilanguageReferrable</code>):</li>\n<li>Bild-/Formelüberschrift mit Verweisbarkeit.</li>\n<li>Aggregiert <code>+desc</code>: <code>MultiLanguageOverviewParagraph [0..1]</code>.</li>\n<li><strong><code>MultiLanguagePlainText</code></strong>:</li>\n<li>Container für sprachabhängige Klartext-Notationen.</li>\n<li>Aggregiert <code>+l10</code>: <code>LPlainText [1..*]</code>.</li>\n<li><strong><code>LPlainText</code></strong> (realisiert <code>LanguageSpecific</code>):</li>\n<li>Einzelsprachlicher Plaintext, spezialisiert die Klasse <code>MixedContentForPlainText</code> (<code>«atpMixedString»</code>, <code>WhitespaceControlled</code>).</li>\n<li><strong><code>MultiLanguageVerbatim</code></strong> (realisiert <code>Paginateable</code>):</li>\n<li>Strukturierter Textblock mit Formatierungssteuerung.</li>\n<li>Attribute:</li>\n<li><code>allowBreak: NameToken [0..1]</code> (Umbruchkontrolle)</li>\n<li><code>float: FloatEnum [0..1]</code> (Gleitobjekt-Verhalten)</li>\n<li><code>helpEntry: String [0..1]</code> (Tooltipp/Hilfereferenz)</li>\n<li><code>pgwide: PgwideEnum [0..1]</code> (Seitenbreite vs. Spaltenbreite im Satzspiegel)</li>\n<li>Aggregiert <code>+l5</code>: <code>LVerbatim [1..*]</code>.</li>\n<li><strong><code>LVerbatim</code></strong> (<code>«atpMixedString»</code>, realisiert <code>LanguageSpecific</code>):</li>\n<li>Sprachspezifischer Verbatim-Text; spezialisiert <code>MixedContentForVerbatim</code> (<code>«atpMixedString»</code>, <code>WhitespaceControlled</code>).</li>\n<li><strong><code>LGraphic</code></strong> (realisiert <code>LanguageSpecific</code>):</li>\n<li>Sprachspezifische Vektor- oder Rastergrafik der Formel.</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten von <code>MlFormula</code></p>\n<ul class=\"fig-list\">\n<li><code>+formulaCaption</code>: <code>Caption [0..1]</code> (Komposition)</li>\n<li><code>+texMath</code>: <code>MultiLanguagePlainText [0..1]</code> (Komposition; TeX/LaTeX-basierte mathematische Notation)</li>\n<li><code>+genericMath</code>: <code>MultiLanguagePlainText [0..1]</code> (Komposition; generische mathematische Syntax/MathML-Klartext)</li>\n<li><code>+verbatim</code>: <code>MultiLanguageVerbatim [0..1]</code> (Komposition; ASCII-/Code-Formatierung)</li>\n<li><code>+lGraphic</code>: <code>LGraphic [0..*]</code> (Komposition; gerenderte Fallback-/Druckgrafiken)</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong></li>\n<li>Es existieren keine Laufzeitpfade, Task-Aktivierungen, RTE-APIs, OS-Hooks oder BSW-Callbacks (Det/Dem).</li>\n<li>Die Verarbeitung erfolgt ausschließlich offline im Rahmen von M2/M1-Modelltransformationen, AUTOSAR-Authoring-Tools und Dokumentations-Generatoren (z. B. DITA/DocBook/PDF-Pipelines).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Serialisierung & Tooling:</strong></li>\n<li>Werkzeuge müssen alternative Repräsentationen derselben Formel parallel handhaben können (z. B. <code>texMath</code> für LaTeX-Export, <code>lGraphic</code> für statische PDF-Generierung).</li>\n<li>Werden Textknoten verwendet (<code>texMath</code>, <code>genericMath</code>, <code>verbatim</code>), erzwingen die Kardinalitäten <code>+l10 [1..<em>]</code> bzw. <code>+l5 [1..</em>]</code> zwingend mindestens ein Sprachelement mit gültigem ISO-Sprachtag (Attribut <code>L</code> aus <code>LanguageSpecific</code>).</li>\n<li><strong>Whitespace-Handling (<code>WhitespaceControlled</code>):</strong></li>\n<li>Parser und Codegeneratoren dürfen Whitespaces, Einrückungen und Zeilenumbrüche in <code>LPlainText</code> und <code>LVerbatim</code> nicht normalisieren oder kollabieren.</li>\n<li><strong>Kein Target-Footprint:</strong></li>\n<li>Diese Elemente sind reine Dokumentationsartefakte; sie erzeugen keinen RAM-/ROM-Footprint und keine Symbole im Target-Code der ECU.</li>\n</ul>"}, {"id": "FIG-8c4450cb79998312", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).</li>\n<li><strong>Architektur-Kontext:</strong> Bestandteil des <em>AUTOSAR Generic Structure Template</em> (TPS_GenericStructureTemplate, Kapitel <em>Documentation Support / Formula Overview</em>).</li>\n<li><strong>Funktionaler Zweck:</strong> Definiert die formale Datenstruktur zur sprachunabhängigen und mehrsprachigen Repräsentation mathematischer Formeln (<code>MlFormula</code>) und technischer Gleichungen innerhalb von AUTOSAR-ARXML-Dateien (z. B. in Spezifikationsblöcken, Requirements-Traces und Software-Komponenten-Beschreibungen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen und Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>MlFormula</code></strong> (realisiert <code>Paginateable</code>):</li>\n<li>Zentraler Container für mathematische Ausdrücke.</li>\n<li><strong><code>Caption</code></strong> (realisiert <code>MultilanguageReferrable</code>):</li>\n<li>Bild-/Formelüberschrift mit Verweisbarkeit.</li>\n<li>Aggregiert <code>+desc</code>: <code>MultiLanguageOverviewParagraph [0..1]</code>.</li>\n<li><strong><code>MultiLanguagePlainText</code></strong>:</li>\n<li>Container für sprachabhängige Klartext-Notationen.</li>\n<li>Aggregiert <code>+l10</code>: <code>LPlainText [1..*]</code>.</li>\n<li><strong><code>LPlainText</code></strong> (realisiert <code>LanguageSpecific</code>):</li>\n<li>Einzelsprachlicher Plaintext, spezialisiert die Klasse <code>MixedContentForPlainText</code> (<code>«atpMixedString»</code>, <code>WhitespaceControlled</code>).</li>\n<li><strong><code>MultiLanguageVerbatim</code></strong> (realisiert <code>Paginateable</code>):</li>\n<li>Strukturierter Textblock mit Formatierungssteuerung.</li>\n<li>Attribute:</li>\n<li><code>allowBreak: NameToken [0..1]</code> (Umbruchkontrolle)</li>\n<li><code>float: FloatEnum [0..1]</code> (Gleitobjekt-Verhalten)</li>\n<li><code>helpEntry: String [0..1]</code> (Tooltipp/Hilfereferenz)</li>\n<li><code>pgwide: PgwideEnum [0..1]</code> (Seitenbreite vs. Spaltenbreite im Satzspiegel)</li>\n<li>Aggregiert <code>+l5</code>: <code>LVerbatim [1..*]</code>.</li>\n<li><strong><code>LVerbatim</code></strong> (<code>«atpMixedString»</code>, realisiert <code>LanguageSpecific</code>):</li>\n<li>Sprachspezifischer Verbatim-Text; spezialisiert <code>MixedContentForVerbatim</code> (<code>«atpMixedString»</code>, <code>WhitespaceControlled</code>).</li>\n<li><strong><code>LGraphic</code></strong> (realisiert <code>LanguageSpecific</code>):</li>\n<li>Sprachspezifische Vektor- oder Rastergrafik der Formel.</li>\n</ul>\n<p class=\"fig-p\">#### Assoziationen & Kardinalitäten von <code>MlFormula</code></p>\n<ul class=\"fig-list\">\n<li><code>+formulaCaption</code>: <code>Caption [0..1]</code> (Komposition)</li>\n<li><code>+texMath</code>: <code>MultiLanguagePlainText [0..1]</code> (Komposition; TeX/LaTeX-basierte mathematische Notation)</li>\n<li><code>+genericMath</code>: <code>MultiLanguagePlainText [0..1]</code> (Komposition; generische mathematische Syntax/MathML-Klartext)</li>\n<li><code>+verbatim</code>: <code>MultiLanguageVerbatim [0..1]</code> (Komposition; ASCII-/Code-Formatierung)</li>\n<li><code>+lGraphic</code>: <code>LGraphic [0..*]</code> (Komposition; gerenderte Fallback-/Druckgrafiken)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong></li>\n<li>Es existieren keine Laufzeitpfade, Task-Aktivierungen, RTE-APIs, OS-Hooks oder BSW-Callbacks (Det/Dem).</li>\n<li>Die Verarbeitung erfolgt ausschließlich offline im Rahmen von M2/M1-Modelltransformationen, AUTOSAR-Authoring-Tools und Dokumentations-Generatoren (z. B. DITA/DocBook/PDF-Pipelines).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ARXML-Serialisierung & Tooling:</strong></li>\n<li>Werkzeuge müssen alternative Repräsentationen derselben Formel parallel handhaben können (z. B. <code>texMath</code> für LaTeX-Export, <code>lGraphic</code> für statische PDF-Generierung).</li>\n<li>Werden Textknoten verwendet (<code>texMath</code>, <code>genericMath</code>, <code>verbatim</code>), erzwingen die Kardinalitäten <code>+l10 [1..<em>]</code> bzw. <code>+l5 [1..</em>]</code> zwingend mindestens ein Sprachelement mit gültigem ISO-Sprachtag (Attribut <code>L</code> aus <code>LanguageSpecific</code>).</li>\n<li><strong>Whitespace-Handling (<code>WhitespaceControlled</code>):</strong></li>\n<li>Parser und Codegeneratoren dürfen Whitespaces, Einrückungen und Zeilenumbrüche in <code>LPlainText</code> und <code>LVerbatim</code> nicht normalisieren oder kollabieren.</li>\n<li><strong>Kein Target-Footprint:</strong></li>\n<li>Diese Elemente sind reine Dokumentationsartefakte; sie erzeugen keinen RAM-/ROM-Footprint und keine Symbole im Target-Code der ECU.</li>\n</ul>"}], "trans": [{"from": "FIG-5855db575eab3985", "to": "FIG-8c4450cb79998312", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
